CURVATURE_SELECTION_SHA256 = '55e30b9a2ba99687f9641cf6a690a0cb52a78e300da95603fd12a9ed2df901e3'
CURVATURE_SOURCE_ONLY = True

def curvature_pins():
    assert sha256(json.dumps(CURVATURE_SELECTED,sort_keys=True,separators=(',',':')).encode()) == CURVATURE_SELECTION_SHA256, \
        'Exact finite curvature selection/provenance drift'
    snapshots = {}
    for commit, oid in CURVATURE_TREES.items():
        assert git('rev-parse',commit+'^{tree}').decode().strip() == oid, 'Finite curvature tree pin drift'
        snapshot = parse_tree(git('ls-tree','-rz',commit))
        assert len(snapshot) == CURVATURE_COUNTS[commit], 'Complete curvature source count drift'
        snapshots[commit] = snapshot
    assert set(CURVATURE_SELECTED) & set(snapshots[CURVATURE_PARENT]) == {'curvature/lakefile.toml'}
    assert len(CURVATURE_SELECTED) == 220
    for path, record in CURVATURE_SELECTED.items():
        assert len(record['origins']) == len({row['head'] for row in record['origins']})
        for origin in record['origins']:
            assert snapshots[origin['head']][path] == tuple(record['mode_blob'])
        data = git('show',record['origins'][0]['head']+':'+path)
        assert blob_id(data) == record['mode_blob'][1] and len(data) == record['bytes']
        assert sha256(data) == record['sha256']
    return snapshots

def curvature_staged_composition_test_inverse(raw):
    assert type(raw) is bytes and sha256(raw)=='7f888229b6a8f4fd2938b788d78827b6a00efcf0fb93d3fa02ba99d70a8817c8', 'Exact staged composition TEST drift'
    edits=(('                            self.assertEqual(reviewed[current_path],original_digest)\n', "                            self.assertEqual(reviewed[current_path],'c35493376e81b27036c332a1330a6ad8c324294c6f69d8b14035adeef3359cc5' if current_path=='.github/workflows/point4-hamilton-release-audit.yml' else original_digest)\n"), ('                            expected[current_path]=reviewed[current_path]=comp.CURVATURE_HAMILTON_SOURCE_SHA256[current_path]\n', "                            expected[current_path]=comp.CURVATURE_HAMILTON_SOURCE_SHA256[current_path]\n                            reviewed[current_path]='aa4e2fa768e975c178a3b61f22999abed8e75d082fac2d695e3d773261297257' if current_path=='.github/workflows/point4-hamilton-release-audit.yml' else expected[current_path]\n"))
    assert sha256(json.dumps(edits,ensure_ascii=False,separators=(',',':')).encode())=='5185d12f5520139b193f184eefe35e60d339da2f8e93383355da1ac59ef93e7c'
    restored=raw.decode('utf8')
    for before,after in reversed(edits):
        assert restored.count(after)==1, 'Staged composition inverse count drift'
        restored=restored.replace(after,before,1)
    assert sha256(restored.encode())=='12da023a1e886a09165f21563ce4c863d7ea86f1eec06ddfa0330ad2301b3186', 'Whole pointwise predecessor TEST drift'
    forward=restored
    for before,after in edits:
        assert forward.count(before)==1 and after not in forward
        forward=forward.replace(before,after,1)
    assert forward.encode()==raw, 'Staged TEST complete forward recovery drift'
    return restored.encode()

def curvature_pointwise_composition_test_inverse(raw):
    assert type(raw) is bytes and sha256(raw)=='12da023a1e886a09165f21563ce4c863d7ea86f1eec06ddfa0330ad2301b3186', 'Exact pointwise composition TEST drift'
    current=b'c887086ba419713560be58da93872c5d1bdc1ac07e8bd1e6a1c90ecc460a7f9a'
    predecessor=b'49a3e72d38f45502eeb7525cb061c41f75320c9c85bfb7c929788d6f04b1a6b9'
    assert raw.count(current)==2 and predecessor not in raw, 'Pointwise composition TEST inverse count drift'
    recovered=raw.replace(current,predecessor)
    assert sha256(recovered)=='e4c8c416b7ab808d2fe1559a8b785ec7839a4bc427f7ca98ad7a26e0200dab35', 'Whole pointwise TEST predecessor drift'
    assert recovered.count(predecessor)==2 and current not in recovered
    assert recovered.replace(predecessor,current)==raw, 'Whole current pointwise TEST recovery drift'
    return recovered

def curvature_hamilton_composition_test_inverse(raw):
    assert type(raw) is bytes and sha256(raw)==CURVATURE_HAMILTON_COMPOSITION_CURRENT_SHA256=='e4c8c416b7ab808d2fe1559a8b785ec7839a4bc427f7ca98ad7a26e0200dab35', 'Exact Hamilton composition source drift'
    edits=CURVATURE_HAMILTON_COMPOSITION_TEST_EDITS
    assert type(edits) is tuple and len(edits)==5, 'Hamilton composition inverse count drift'
    serial=json.dumps(edits,sort_keys=True,ensure_ascii=False,separators=(',',':')).encode()
    assert sha256(serial)==CURVATURE_HAMILTON_COMPOSITION_POLICY_SHA256=='e1ec3dcad858982164e697b7053aa9d40a9b8923376dcb3719a0228872824e94', 'Hamilton composition inverse policy drift'
    recovered=raw.decode('utf8')
    for before,after in reversed(edits):
        assert type(before) is str and type(after) is str and before!=after
        assert recovered.count(after)==1, 'Missing/duplicate Hamilton composition inverse'
        recovered=recovered.replace(after,before,1)
    restored=recovered.encode('utf8')
    assert sha256(restored)==CURVATURE_HAMILTON_COMPOSITION_ORIGINAL_SHA256=='99d551f063c426203445338f16a646505e08c963612a3ea22f82f2b85345e1c4', 'Whole coherent composition predecessor drift'
    forward=recovered
    for before,after in edits:
        assert forward.count(before)==1 and after not in forward, 'Hamilton composition forward inverse drift'
        forward=forward.replace(before,after,1)
    assert forward.encode('utf8')==raw, 'Complete current Hamilton composition recovery drift'
    assert sha256(json.dumps(CURVATURE_HAMILTON_COMPOSITION_TEST_EDITS,sort_keys=True,ensure_ascii=False,separators=(',',':')).encode())=='e1ec3dcad858982164e697b7053aa9d40a9b8923376dcb3719a0228872824e94'
    return restored

def curvature_section_inverse(raw, path, marker):
    if path==TEST:raw=curvature_staged_composition_test_inverse(raw)
    if path==TEST:raw=curvature_pointwise_composition_test_inverse(raw)
    if path==TEST:raw=curvature_hamilton_composition_test_inverse(raw)
    if path==TEST:raw=curvature_smooth_split_test_inverse(raw)
    start = ('# BEGIN authenticated finite curvature '+marker+'\n').encode()
    end = ('# END authenticated finite curvature '+marker+'\n').encode()
    assert raw.count(start) == raw.count(end) == 1, 'Curvature extension boundary drift'
    first = raw.index(start)
    last = raw.index(end, first)+len(end)
    restored = raw[:first]+raw[last:]
    if path == TEST:
        current_input_line = b'            expected = comp.curvature_identity(expected,originals,changes)[0]\n'
        assert restored.count(current_input_line) == 1, 'Finite current identity assertion extension drift'
        restored = restored.replace(current_input_line,b'',1)
        old_count = b'            self.assertEqual(len(expected), 1920)\n'
        new_count = b'            self.assertEqual(len(expected), 2139)\n'
        assert restored.count(new_count) == 1, 'Exact current identity count assertion drift'
        restored = restored.replace(new_count,old_count,1)
        old_unchanged = b'            unchanged = set(trees[FIXED_PARENT_PIN]) - comp.EDITED - comp.NEW - comp.FIXED_ROOTS - comp.TENSOR_PATHS\n'
        new_unchanged = old_unchanged.rstrip(b'\n')+b' - set(comp.CURVATURE_SELECTED)\n'
        assert restored.count(new_unchanged) == 1, 'Exact finite selected input assertion drift'
        restored = restored.replace(new_unchanged,old_unchanged,1)
        old_weighted = b'    def test_genuine_weighted_reconstruction_positive_and_adversarial_records(self):\n        import point4_weighted_hessian_release_guard as weighted\n        import stat\n        self.assertEqual(weighted.ROOT,comp.ROOT)\n        expected,originals,changes=self.inputs()\n'
        new_weighted = old_weighted.replace(b'expected,originals,changes=self.inputs()',b'expected,originals,changes=comp.curvature_identity(*self.inputs())')
        assert restored.count(new_weighted) == 1, 'Full-current genuine weighted fixture drift'
        restored = restored.replace(new_weighted,old_weighted,1)
        old_report = b"            self.assertEqual(report['public_paths'],1920)\n"
        new_report = b"            self.assertEqual(report['public_paths'],2139)\n"
        assert restored.count(new_report) == 1, 'Exact current weighted namespace count drift'
        restored = restored.replace(new_report,old_report,1)
        before = b'    suite.addTests(unittest.defaultTestLoader.loadTestsFromTestCase(TensorCompositionTests))\n'
        after = before+b'    suite.addTests(unittest.defaultTestLoader.loadTestsFromTestCase(CurvatureCompositionTests))\n'+b'    suite.addTests(unittest.defaultTestLoader.loadTestsFromTestCase(CurvatureProductionNamespaceTests))\n'
        assert restored.count(after) == 1, 'Finite curvature test-suite hook drift'
        restored = restored.replace(after,before,1)
    assert restored == git('show',CURVATURE_PARENT+':'+path), 'Complete curvature predecessor executable drift'
    return restored

_curvature_original_helper_inverse = tensor_helper_inverse
_curvature_original_test_inverse = tensor_test_inverse
_curvature_original_tensor_identity = tensor_identity
_curvature_original_tensor_map_record = tensor_map_record
_curvature_original_verify_current = verify_current
_curvature_original_reconstructed_sources = tensor_reconstructed_sources
_curvature_verification_active = False

def tensor_identity(*args):
    result = _curvature_original_tensor_identity(*args)
    return curvature_identity(*result) if _curvature_verification_active else result

def tensor_helper_inverse(raw):
    return _curvature_original_helper_inverse(curvature_section_inverse(raw,HELPER,'extension'))

def tensor_test_inverse(raw):
    return _curvature_original_test_inverse(curvature_section_inverse(raw,TEST,'tests'))

def curvature_predecessor(expected, originals, changes, snapshots):
    parent = snapshots[CURVATURE_PARENT]
