def curvature_component_frozen(value,key,seen=()):
    if type(value) in (str,bytes,int,float,bool,type(None)):return ('literal',value)
    assert id(value) not in seen and len(seen)<32, 'Recursive embedded sealed value drift'
    nested=(*seen,id(value))
    if type(value) in (dict,types.MappingProxyType):
        return ('mapping',frozenset((curvature_component_frozen(k,key+'/key',nested),
            curvature_component_frozen(v,key+'/value',nested)) for k,v in value.items()))
    if type(value) in (set,frozenset):return ('set',frozenset(curvature_component_frozen(v,key+'/item',nested) for v in value))
    if type(value) in (list,tuple):return (type(value).__name__,tuple(curvature_component_frozen(v,key+'/item',nested) for v in value))
    if isinstance(value,types.FunctionType) or callable(value) and hasattr(value,'__wrapped__'):
        return curvature_component_snapshot(value,key,seen)
    return ('identity',id(value))

def curvature_component_snapshot(value,key,seen=()):
    assert id(value) not in seen and len(seen)<32, 'Recursive embedded function wrapper drift'
    if isinstance(value,types.FunctionType):
        wrapped=curvature_component_snapshot(value.__wrapped__,key+'/wrapped',(*seen,id(value))) if hasattr(value,'__wrapped__') else None
        closure=tuple(('namespace',id(cell.cell_contents)) if name=='namespace' and type(cell.cell_contents) is dict
            or cell.cell_contents is value.__globals__ else curvature_component_frozen(cell.cell_contents,key+'/closure/'+name,(*seen,id(value)))
            for name,cell in zip(value.__code__.co_freevars,value.__closure__ or ()))
        return ('function',value,value.__code__,id(value.__globals__),curvature_component_frozen(value.__defaults__,key+'/defaults'),
            curvature_component_frozen(value.__kwdefaults__,key+'/kwdefaults'),curvature_component_frozen(value.__annotations__,key+'/annotations'),closure,wrapped)
    if callable(value) and hasattr(value,'__wrapped__'):
        import functools
        assert type(value) is functools._lru_cache_wrapper, 'Unknown embedded callable wrapper'
        for name in ('cache_info','cache_clear'):
            assert getattr(value,name)==getattr(type(value),name).__get__(value), 'Embedded cache method drift'
        return ('wrapped',value,value.cache_info().maxsize,
            curvature_component_snapshot(value.cache_parameters,key+'/cache_parameters',(*seen,id(value))),
            curvature_component_snapshot(value.__wrapped__,key+'/wrapped',(*seen,id(value))))
    if key!='__builtins__' and type(value) in (dict,set,list,tuple):return ('data',curvature_component_frozen(value,key))
    return ('identity',value)

def curvature_registration_snapshot(bindings):
    assert type(bindings) is dict, 'Registration registry type drift'
    result=[]
    for identifier,record in sorted(bindings.items()):
        assert type(record) is types.MappingProxyType and set(record)=={'namespace','number','comp','bindings','originals'}, 'Registration record structure drift'
        assert identifier==id(record['namespace']) and type(record['namespace']) is dict
        assert record['comp'] is sys.modules[__name__]
        assert type(record['bindings']) is types.MappingProxyType and type(record['originals']) is types.MappingProxyType
        expected_names={'main','expected_sources','public_paths'} if record['number'] in (111,132,134) else {'main'} if record['number']==136 else {'admit','check_probe'} if record['number']==138 else None
        assert expected_names is not None and set(record['originals'])==expected_names, 'Registration original-target set drift'
        result.append((identifier,id(record),id(record['namespace']),id(record['comp']),record['number'],
            tuple(sorted(record['bindings'].items())),tuple((name,curvature_component_snapshot(value,name))
                for name,value in sorted(record['originals'].items()))))
    return tuple(result)

def curvature_registration_check(name,bindings):
    seals=dict(_curvature_registration_seals)
    assert len(seals)==len(_curvature_registration_seals)==2 and name in seals
    assert _curvature_modules[name]._BINDINGS is bindings
    assert curvature_registration_snapshot(bindings)==seals[name], 'Registration immutable seal drift: '+name

def curvature_registration_add(name,bindings,record):
    global _curvature_registration_seals
    curvature_registration_check(name,bindings)
    owner=_curvature_install_owner;frame=sys._getframe(1)
    assert owner is not None and owner[1]==name and owner[2] is record['namespace'] and owner[3]==record['number'], 'Foreign registration transaction'
    assert owner[4] is _curvature_modules[name].install and owner[5] is owner[4].__code__
    assert frame.f_code is owner[5] and frame.f_globals is _curvature_modules[name].__dict__, 'Registration did not originate in source-bound installation'
    assert frame.f_locals['namespace'] is record['namespace'] and frame.f_locals['number']==record['number'] and frame.f_locals['record'] is record
    assert record['comp'] is sys.modules[__name__] and id(record['namespace']) not in bindings
    before=dict(_curvature_registration_seals)[name]
    bindings[id(record['namespace'])]=record
    try:after=curvature_registration_snapshot(bindings)
    except BaseException:
        bindings.pop(id(record['namespace']),None);raise
    _curvature_registration_seals=tuple((key,after if key==name else seal) for key,seal in _curvature_registration_seals)
    return before

def curvature_registration_rollback(name,bindings,before):
    global _curvature_registration_seals
    assert _curvature_modules[name]._BINDINGS is bindings
    owner=_curvature_install_owner;frame=sys._getframe(1)
    assert owner is not None and owner[1]==name and owner[4] is _curvature_modules[name].install, 'Foreign registry rollback transaction'
    assert frame.f_code is owner[5] is owner[4].__code__ and frame.f_globals is _curvature_modules[name].__dict__, 'Foreign registry rollback transaction'
    assert frame.f_locals['prior'] is before and frame.f_locals['namespace'] is owner[2]
    assert curvature_registration_snapshot(bindings)==before, 'Registration rollback altered another entry'
    _curvature_registration_seals=tuple((key,before if key==name else seal) for key,seal in _curvature_registration_seals)
    curvature_registration_check(name,bindings)

def curvature_install_registration(name,namespace,number):
    global _curvature_install_owner
    assert type(namespace) is dict and (name,number) in {('curvature_leaf_binding',111),('curvature_leaf_binding',132),
        ('curvature_leaf_binding',134),('curvature_auxiliary_binding',136),('curvature_auxiliary_binding',138)}
    module=curvature_embedded_module(name)
    assert _curvature_install_owner is None, 'Recursive or foreign registration installation'
    owner=(object(),name,namespace,number,module.install,module.install.__code__)
    _curvature_install_owner=owner;primary=None
    try:return module.install(sys.modules[__name__],namespace,number)
    except BaseException as error:primary=error;raise
    finally:
        changed=_curvature_install_owner is not owner
        _curvature_install_owner=None
        if changed:
            error=AssertionError('Registration installation owner mutated')
            if primary is None:raise error
            primary.add_note(repr(error))

def curvature_component_check(key,module):
    bindings=_curvature_component_bindings[key]
    assert set(module.__dict__)==set(bindings), 'Embedded runtime namespace keys drift: '+key
    for name,wanted in bindings.items():
        actual=module.__dict__[name]
        if wanted[0]=='identity':assert actual is wanted[1], 'Embedded runtime binding drift: '+key+'/'+name
        else:assert curvature_component_snapshot(actual,name)==wanted, 'Embedded runtime code/policy drift: '+key+'/'+name
    if key in ('curvature_leaf_binding','curvature_auxiliary_binding'):
        curvature_registration_check(key,module._BINDINGS)

def curvature_embedded_module(name):
    assert set(CURVATURE_EMBEDDED_SOURCES)==set(CURVATURE_EMBEDDED_SOURCE_SHA256)
    assert name in CURVATURE_EMBEDDED_ORDER
    for key in CURVATURE_EMBEDDED_ORDER:
        raw=CURVATURE_EMBEDDED_SOURCES[key]
        assert sha256(raw.encode())==CURVATURE_EMBEDDED_SOURCE_SHA256[key], 'Embedded curvature source identity drift'
        if key in _curvature_modules:
            module=_curvature_modules[key]
            assert sys.modules.get(key) is module
            assert module.__file__==str(ROOT/HELPER)
            assert module._point4_exact_source_sha256==CURVATURE_EMBEDDED_SOURCE_SHA256[key]
            curvature_component_check(key,module)
        else:
            assert key not in sys.modules, 'Foreign curvature component module already installed'
            module=types.ModuleType(key);module.__file__=str(ROOT/HELPER)
            sys.modules[key]=module
            try:exec(compile(raw,str(ROOT/HELPER)+'/'+key,'exec',dont_inherit=True),module.__dict__)
            except BaseException:
                assert sys.modules.get(key) is module
                sys.modules.pop(key);raise
            module._point4_exact_source_sha256=CURVATURE_EMBEDDED_SOURCE_SHA256[key]
            # The two registration dictionaries have a separate immutable
            # seal for every entry, outside the records checked against it.
            _curvature_component_bindings[key]={name:(('identity',value) if name=='_BINDINGS'
                and key in ('curvature_leaf_binding','curvature_auxiliary_binding') else curvature_component_snapshot(value,name))
                for name,value in module.__dict__.items()}
            _curvature_modules[key]=module
    return _curvature_modules[name]

def install_curvature_leaf(namespace,number):
    return curvature_install_registration('curvature_leaf_binding',namespace,number)

def curvature_leaf_namespace_binding(namespace,number):
    return curvature_embedded_module('curvature_leaf_binding').check(sys.modules[__name__],namespace,number)

def run_curvature_mocks(number,path,args):
    return curvature_embedded_module('curvature_leaf_execution').run_mocks(sys.modules[__name__],number,path,args)

def install_curvature_auxiliary(namespace,number):
    return curvature_install_registration('curvature_auxiliary_binding',namespace,number)

def curvature_chart_namespace_binding(namespace):
    return curvature_embedded_module('curvature_auxiliary_binding').check(sys.modules[__name__],namespace,138)

def curvature_scalar_namespace_binding(namespace):
    return curvature_embedded_module('curvature_auxiliary_binding').check(sys.modules[__name__],namespace,136)

def run_curvature_auxiliary_mocks(number,path,args):
    return curvature_embedded_module('curvature_auxiliary_execution').run_mocks(sys.modules[__name__],number,path,args)
