def curvature_selected_source(path,digest=None):
    selected=CURVATURE_SELECTED[path]
    original=git('show',selected['origins'][0]['head']+':'+path)
    assert sha256(original)==selected['sha256'] and blob_id(original)==selected['mode_blob'][1]
    if path=='curvature/PoincareCurvature/Geometry/Manifold/RicciFlow/AnalyticPDE/C0FiniteAtlasGaussian.lean':return curvature_endpoint_api_source(original)
    if path=='.github/workflows/point4-c2-resonance.yml':return curvature_scalar_audit_workflow_source(original)
    if path in CURVATURE_HAMILTON_SOURCE_EDITS:
        current_digest=sha256((ROOT/HELPER).read_bytes())
        if digest is None or digest==current_digest:return curvature_hamilton_current_source(path,original)
        return original # Immutable predecessor helper reconstruction.
    if path not in CURVATURE_EXECUTABLE_PATHS:return original
    if digest is None:digest=sha256((ROOT/HELPER).read_bytes())
    kind,number=CURVATURE_EXECUTABLE_PATHS[path]
    if kind=='leaf':
        module=curvature_embedded_module('curvature_leaf_transforms')
        changed=module.transform(number,path,original,digest)
        assert module.inverse(number,path,changed,digest)==original
    elif kind=='auxiliary':
        module=curvature_embedded_module('curvature_auxiliary_transforms')
        changed=module.transform(number,original,digest)
        assert module.inverse(number,changed,digest)==original
    elif kind=='auxiliary-mock':
        module=curvature_embedded_module('curvature_auxiliary_transforms')
        changed=module.mock_transform(original,digest)
        assert module.mock_inverse(changed,digest)==original
    elif kind=='chart-ci':
        anchor=b"    bootstrap_visit('Cache.Main')\n"
        added=CURVATURE_CHART_CI_ADDITION.encode()
        assert original.count(anchor)==1 and added not in original
        changed=original.replace(anchor,added+anchor,1)
        old_call,new_call=CURVATURE_CHART_BOOTSTRAP_CALL
        assert original.count(old_call)==1 and new_call not in original
        changed=changed.replace(old_call,new_call,1)
        for before,after in CURVATURE_CHART_CI_EDITS:
            assert changed.count(before)==1 and after not in changed
            changed=changed.replace(before,after,1)
        assert sha256(changed)==CURVATURE_CHART_CI_SHA256
        assert changed.count(new_call)==1 and changed.count(added)==1
        recovered=changed
        for before,after in reversed(CURVATURE_CHART_CI_EDITS):
            assert recovered.count(after)==1
            recovered=recovered.replace(after,before,1)
        assert recovered.replace(new_call,old_call,1).replace(added,b'',1)==original
    elif kind=='chart-artifacts':
        before,after=CURVATURE_CHART_ARTIFACT_TRANSFORM
        assert original.decode()==before
        changed=after.encode()
        assert sha256(changed)==CURVATURE_CHART_ARTIFACT_SHA256
    else:
        assert kind=='chart-test'
        changed=original.decode()
        for before,after in CURVATURE_CHART_TEST_EDITS:
            assert changed.count(before)==1;changed=changed.replace(before,after,1)
        marker="if __name__ == '__main__':\n"
        added=CURVATURE_CHART_TEST_ADDITION
        assert changed.count(marker)==1 and added not in changed
        changed=changed.replace(marker,added+marker,1)
        changed=changed.encode();assert sha256(changed)==CURVATURE_CHART_TEST_SHA256
        recovered=changed.decode()
        assert recovered.count(added)==1
        recovered=recovered.replace(added,'',1)
        for before,after in reversed(CURVATURE_CHART_TEST_EDITS):
            assert recovered.count(after)==1;recovered=recovered.replace(after,before,1)
        assert recovered.encode()==original
        import ast
        def tests(raw):return [ast.dump(n,include_attributes=False) for item in ast.parse(raw).body
            if isinstance(item,ast.ClassDef) for n in item.body
            if isinstance(n,ast.FunctionDef) and n.name.startswith('test_')]
        assert tests(original)==tests(changed.replace(added.encode(),b'',1)), 'Original chart test body drift'
    return changed
